def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS/DFS to find cycles of specific length
    def find_cycle(start, current, path, visited):
        if len(path) == length:
            return start in adj[current]
        for neighbor in adj[current]:
            if neighbor == start and len(path) == length - 1:
                return True
            if neighbor not in visited and neighbor != start:
                visited.add(neighbor)
                if find_cycle(start, neighbor, path + [neighbor], visited):
                    return True
                visited.remove(neighbor)
        return False

    for start in range(n):
        visited = {start}
        for neighbor in adj[start]:
            visited.add(neighbor)
            if find_cycle(start, neighbor, [start, neighbor], visited):
                return True
            visited.remove(neighbor)
    return False

