import itertools
import random

def check_bipartite_girth(edges, A, B):
    """Check if bipartite graph has girth >= 8 (no 4-cycles or 6-cycles)."""
    adj_a = {u: set() for u in A}
    adj_b = {v: set() for v in B}
    for u, v in edges:
        if u in A:
            adj_a[u].add(v)
            adj_b[v].add(u)
        else:
            adj_a[v].add(u)
            adj_b[u].add(v)

    # Check 4-cycles: two vertices in A sharing 2+ neighbors in B
    for u1, u2 in itertools.combinations(A, 2):
        if len(adj_a[u1] & adj_a[u2]) >= 2:
            return False

    # Check 6-cycles more efficiently
    # A 6-cycle in bipartite: u1-v1-u2-v2-u3-v3-u1
    # This means: u1,u2,u3 in A; v1,v2,v3 in B
    # u1 adjacent to v1,v3; u2 adjacent to v1,v2; u3 adjacent to v2,v3

    # For each pair (u1, u2) in A sharing a neighbor v1 in B,
    # check if there's a path of length 4 from u1 to u2 not using v1
    for u1, u2 in itertools.combinations(A, 2):
        shared = adj_a[u1] & adj_a[u2]
        if len(shared) >= 2:
            return False  # 4-cycle
        for v1 in shared:
            # Look for u3 in A (not u1, u2) and v2, v3 in B (not v1)
            # such that u1-v3-u3-v2-u2 forms a path
            for u3 in A:
                if u3 in (u1, u2):
                    continue
                # u3 must connect to some v2, v3
                # u1 must connect to v3, u2 must connect to v2
                for v3 in adj_a[u1]:
                    if v3 == v1:
                        continue
                    if v3 not in adj_a[u3]:
                        continue
                    for v2 in adj_a[u2]:
                        if v2 == v1 or v2 == v3:
                            continue
                        if v2 in adj_a[u3]:
                            return False  # 6-cycle found

    return True

