def find_shortest_cycle():
    """Find the shortest cycle in the graph."""
    min_cycle = float('inf')

    for start in range(n):
        # BFS from start
        # dist[v] = distance from start to v
        # parent[v] = parent of v in BFS tree
        dist = {start: 0}
        parent = {start: None}
        queue = [start]

        while queue:
            curr = queue.pop(0)
            for neighbor in adj[curr]:
                if neighbor not in dist:
                    dist[neighbor] = dist[curr] + 1
                    parent[neighbor] = curr
                    queue.append(neighbor)
                elif neighbor != parent.get(curr):
                    # Found a cycle
                    cycle_len = dist[curr] + dist[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

